/* ---- lib/fs/fs.c ---- */
/* Natives of package fs (runtime/README.md, "Native functions"). Errors
 * follow docs/stdlib.md: "fs.<function>: <path>: <reason>", and
 * "fs.File.<method>: <path>: <reason>" for the methods of File. */

#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

static sd_err fs_errorf(const char *fn, const char *path, int e) { return sd_errorf("fs.%s: %s: %s", fn, path, sd_strerror(e)); }

/* Paths go to the OS as C strings, which end at the first NUL byte: a path
 * with a NUL inside would name a different file ("dir/\0x" is "dir/", so
 * removeAll would remove dir). Such a path is an error, as in Go; the
 * subject shows each NUL as \x00. */
static bool fs_has_nul(sd_str s) { return s->len > 0 && memchr(s->data, 0, (size_t)s->len) != NULL; }

static char *fs_show(sd_str s) {
  char *out = sd_alloc((size_t)s->len * 4 + 1), *q = out;
  for (int64_t i = 0; i < s->len; i++) {
    if (s->data[i] == 0) {
      memcpy(q, "\\x00", 4);
      q += 4;
    } else {
      *q++ = s->data[i];
    }
  }
  *q = 0;
  return out;
}

static sd_err fs_nul_error(const char *fn, sd_str path) {
  char *shown = fs_show(path);
  sd_err e = sd_errorf("fs.%s: %s: path contains a NUL byte", fn, shown);
  free(shown);
  return e;
}

#define FS_CHECK_PATH(fn, path) \
  do { \
    if (fs_has_nul(path)) return fs_nul_error(fn, path); \
  } while (0)

/* Writes all n bytes to fd, retrying after signals and short writes.
 * Returns 0 or the errno. */
static int fs_write_all(int fd, const char *p, size_t n) {
  while (n > 0) {
    ssize_t w = write(fd, p, n);
    if (w < 0 && errno == EINTR) continue;
    if (w < 0) return errno;
    if (w == 0) return EIO;
    p += w;
    n -= (size_t)w;
  }
  return 0;
}

static int fs_open_retry_blocking(const char *path, int flags, mode_t mode);

/* open() may block (a FIFO waits for its other end): in a block section. */
static int fs_open_retry(const char *path, int flags, mode_t mode) {
  sd_block_begin();
  int fd = fs_open_retry_blocking(path, flags, mode);
  sd_block_end();
  return fd;
}

static int fs_open_retry_blocking(const char *path, int flags, mode_t mode) {
  int fd;
  do fd = open(path, flags | O_CLOEXEC, mode);
  while (fd < 0 && errno == EINTR);
  return fd;
}

/* ------------------------------------------------------- whole files */

sd_err sd_lib_fs_read(sd_str path, sd_str *out) {
  FS_CHECK_PATH("read", path);
  return sd_fs_read(path, out);
}

static sd_err fs_write_blocking(sd_str path, sd_str data) {
  FS_CHECK_PATH("write", path);
  int fd = fs_open_retry(path->data, O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (fd < 0) return fs_errorf("write", path->data, errno);
  int e = fs_write_all(fd, data->data, (size_t)data->len);
  if (close(fd) != 0 && e == 0 && errno != EINTR) e = errno;
  if (e) return fs_errorf("write", path->data, e);
  return SD_ERR_NULL;
}

/* One append at a time in this process, so that two goroutines' appends
 * never interleave even when a write() is cut short; O_APPEND keeps whole
 * writes from different processes apart on a local file system. */
static pthread_mutex_t fs_append_mu = PTHREAD_MUTEX_INITIALIZER;

static sd_err fs_append_blocking(sd_str path, sd_str data) {
  FS_CHECK_PATH("append", path);
  int fd = fs_open_retry(path->data, O_WRONLY | O_CREAT | O_APPEND, 0644);
  if (fd < 0) return fs_errorf("append", path->data, errno);
  pthread_mutex_lock(&fs_append_mu);
  int e = fs_write_all(fd, data->data, (size_t)data->len);
  pthread_mutex_unlock(&fs_append_mu);
  if (close(fd) != 0 && e == 0 && errno != EINTR) e = errno;
  if (e) return fs_errorf("append", path->data, e);
  return SD_ERR_NULL;
}

bool sd_lib_fs_exists(sd_str path) { return !fs_has_nul(path) && sd_fs_exists(path); }

bool sd_lib_fs_isDir(sd_str path) { return !fs_has_nul(path) && sd_fs_is_dir(path); }

static sd_err fs_stat_blocking(sd_str path, sd_S_fs_Info *out) {
  FS_CHECK_PATH("stat", path);
  struct stat st;
  if (stat(path->data, &st) != 0) return fs_errorf("stat", path->data, errno);
#if defined(__APPLE__)
  int64_t sec = (int64_t)st.st_mtimespec.tv_sec, nsec = (int64_t)st.st_mtimespec.tv_nsec;
#else
  int64_t sec = (int64_t)st.st_mtim.tv_sec, nsec = (int64_t)st.st_mtim.tv_nsec;
#endif
  out->f_size = sd_int_from_i64((int64_t)st.st_size);
  out->f_isDir = S_ISDIR(st.st_mode);
  out->f_modified = sd_int_from_i64(sec * 1000000000 + nsec);
  return SD_ERR_NULL;
}

/* ------------------------------------------------------- directories */

sd_err sd_lib_fs_list(sd_str dir, sd_list **out) {
  FS_CHECK_PATH("list", dir);
  return sd_fs_list(dir, out);
}

/* Like the runtime's sd_fs_mkdir (error messages included), with the mode
 * docs/stdlib.md gives. */
static sd_err fs_mkdir_blocking(sd_str path) {
  FS_CHECK_PATH("mkdir", path);
  char *cp = sd_alloc((size_t)path->len + 1);
  memcpy(cp, path->data, (size_t)path->len + 1);
  size_t n = strlen(cp);
  for (size_t i = 1; i <= n; i++) {
    if (i < n && cp[i] != '/') continue;
    char c = cp[i];
    cp[i] = 0;
    if (mkdir(cp, 0755) != 0 && errno != EEXIST) {
      sd_err err = fs_errorf("mkdir", path->data, errno);
      free(cp);
      return err;
    }
    cp[i] = c;
  }
  struct stat st;
  sd_err err = SD_ERR_NULL;
  if (stat(cp, &st) != 0 || !S_ISDIR(st.st_mode)) err = fs_errorf("mkdir", path->data, ENOTDIR);
  free(cp);
  return err;
}

static sd_err fs_rename_blocking(sd_str from, sd_str to) {
  if (fs_has_nul(from) || fs_has_nul(to)) {
    char *a = fs_show(from), *b = fs_show(to);
    sd_err e = sd_errorf("fs.rename: %s -> %s: path contains a NUL byte", a, b);
    free(a);
    free(b);
    return e;
  }
  if (rename(from->data, to->data) != 0) return sd_errorf("fs.rename: %s -> %s: %s", from->data, to->data, sd_strerror(errno));
  return SD_ERR_NULL;
}

static sd_err fs_remove_blocking(sd_str path) {
  FS_CHECK_PATH("remove", path);
  return sd_fs_remove(path);
}

static char *fs_join(const char *dir, const char *name) {
  size_t a = strlen(dir), b = strlen(name);
  char *p = sd_alloc(a + b + 2);
  memcpy(p, dir, a);
  p[a] = '/';
  memcpy(p + a + 1, name, b + 1);
  return p;
}

/* Removes path and what is inside it, without following symbolic links.
 * The names in a directory are read first and removed after closing it, so
 * that removing does not disturb readdir. */
static sd_err fs_remove_tree(const char *path) {
  struct stat st;
  if (lstat(path, &st) != 0) {
    if (errno == ENOENT) return SD_ERR_NULL;
    return fs_errorf("removeAll", path, errno);
  }
  if (!S_ISDIR(st.st_mode)) {
    if (unlink(path) != 0 && errno != ENOENT) return fs_errorf("removeAll", path, errno);
    return SD_ERR_NULL;
  }
  DIR *d = opendir(path);
  if (!d) return fs_errorf("removeAll", path, errno);
  size_t n = 0, cap = 16;
  char **names = sd_alloc(cap * sizeof(char *));
  struct dirent *de;
  while ((de = readdir(d))) {
    if (!strcmp(de->d_name, ".") || !strcmp(de->d_name, "..")) continue;
    if (n == cap) {
      cap *= 2;
      names = sd_realloc(names, cap * sizeof(char *));
    }
    names[n++] = fs_join(path, de->d_name);
  }
  closedir(d);
  sd_err err = SD_ERR_NULL;
  for (size_t i = 0; i < n; i++) {
    if (sd_err_is_null(err)) err = fs_remove_tree(names[i]);
    free(names[i]);
  }
  free(names);
  if (!sd_err_is_null(err)) return err;
  if (rmdir(path) != 0 && errno != ENOENT) return fs_errorf("removeAll", path, errno);
  return SD_ERR_NULL;
}

static sd_err fs_removeAll_blocking(sd_str path) {
  FS_CHECK_PATH("removeAll", path);
  if (path->len == 0) return SD_ERR_NULL;
  return fs_remove_tree(path->data);
}

static sd_err fs_makeTemp_blocking(sd_str prefix, sd_str *out) {
  FS_CHECK_PATH("makeTemp", prefix);
  const char *dir = getenv("TMPDIR");
  if (!dir || !*dir) dir = "/tmp";
  size_t dl = strlen(dir);
  while (dl > 1 && dir[dl - 1] == '/') dl--;
  size_t pl = (size_t)prefix->len;
  char *tmpl = sd_alloc(dl + 1 + pl + 7);
  memcpy(tmpl, dir, dl);
  tmpl[dl] = '/';
  memcpy(tmpl + dl + 1, prefix->data, pl);
  memcpy(tmpl + dl + 1 + pl, "XXXXXX", 7);
  if (!mkdtemp(tmpl)) {
    tmpl[dl + 1 + pl] = 0;
    sd_err err = fs_errorf("makeTemp", tmpl, errno);
    free(tmpl);
    return err;
  }
  *out = sd_str_from_cstr(tmpl);
  free(tmpl);
  return SD_ERR_NULL;
}

/* ------------------------------------------------------- File handles */

/* A File is an entry of the runtime's handle table (runtime/README.md,
 * section 13; kind SD_HANDLE_FILE), shared with io and net: the File holds
 * its id, whether it was opened for writing, and the path (for messages,
 * also after close). The table makes every operation atomic (one at a
 * time per handle), and its reads poll before they read, so a read is a
 * stop point (a FIFO can block for ever). Ids are never reused, so a stale
 * copy of a closed File finds nothing and says "file is closed". */

static sd_err fs_open_file(const char *fn, sd_str path, int flags, bool writing, sd_S_fs_File *out) {
  FS_CHECK_PATH(fn, path);
  int fd = fs_open_retry(path->data, flags, 0644);
  if (fd < 0) return fs_errorf(fn, path->data, errno);
  if (!writing) {
    struct stat st;
    if (fstat(fd, &st) == 0 && S_ISDIR(st.st_mode)) {
      close(fd);
      return fs_errorf(fn, path->data, EISDIR);
    }
  }
  out->f_id = sd_int_from_i64(sd_handle_new(SD_HANDLE_FILE, fd, path->data));
  out->f_writing = writing;
  out->f_path = sd_str_retain(path);
  return SD_ERR_NULL;
}

sd_err sd_lib_fs_open(sd_str path, sd_S_fs_File *out) { return fs_open_file("open", path, O_RDONLY, false, out); }

sd_err sd_lib_fs_create(sd_str path, sd_S_fs_File *out) {
  return fs_open_file("create", path, O_WRONLY | O_CREAT | O_TRUNC, true, out);
}

/* The handle of f, acquired (released with sd_handle_release) and open for
 * reading (want_write false) or writing; otherwise NULL with *err set. */
static sd_handle *fs_handle_use(sd_S_fs_File f, const char *method, bool want_write, sd_err *err) {
  const char *why = NULL;
  if (want_write && !f.f_writing) why = "file is open for reading only";
  else if (!want_write && f.f_writing) why = "file is open for writing only";
  sd_handle *h = NULL;
  int64_t id;
  if (!why && sd_int_to_i64(f.f_id, &id)) h = sd_handle_acquire(id, SD_HANDLE_FILE);
  if (h) return h;
  *err = sd_errorf("fs.File.%s: %s: %s", method, f.f_path->data, why ? why : "file is closed");
  return NULL;
}

/* The error for a handle I/O result other than SD_IO_OK and SD_IO_EOF. */
static sd_err fs_io_error(const char *method, sd_S_fs_File f, int r, int e) {
  if (r == SD_IO_CLOSED) return sd_errorf("fs.File.%s: %s: file is closed", method, f.f_path->data);
  if (r == SD_IO_TIMEOUT) return sd_errorf("fs.File.%s: %s: timeout", method, f.f_path->data);
  return sd_errorf("fs.File.%s: %s: %s", method, f.f_path->data, sd_strerror(e));
}

sd_err sd_lib_fs_File_readLine(sd_S_fs_File f, sd_str *out) {
  sd_err err = SD_ERR_NULL;
  sd_handle *h = fs_handle_use(f, "readLine", false, &err);
  if (!h) return err;
  int e = 0;
  int r = sd_handle_read_line(h, out, &e);
  if (r != SD_IO_OK && r != SD_IO_EOF) err = fs_io_error("readLine", f, r, e);
  sd_handle_release(h);
  return err;
}

sd_err sd_lib_fs_File_read(sd_S_fs_File f, sd_int max, sd_str *out) {
  int64_t m;
  if (!sd_int_to_i64(max, &m)) m = sd_int_lt(max, SD_INT(0)) ? -1 : INT64_MAX;
  if (m < 1) {
    sd_crash_int("fs.File.read: max (%s) must be at least 1", max);
  }
  sd_err err = SD_ERR_NULL;
  sd_handle *h = fs_handle_use(f, "read", false, &err);
  if (!h) return err;
  int e = 0;
  int r = sd_handle_read(h, m, out, &e);
  if (r != SD_IO_OK && r != SD_IO_EOF) err = fs_io_error("read", f, r, e);
  sd_handle_release(h);
  return err;
}

sd_err sd_lib_fs_File_write(sd_S_fs_File f, sd_str data) {
  sd_err err = SD_ERR_NULL;
  sd_handle *h = fs_handle_use(f, "write", true, &err);
  if (!h) return err;
  int e = 0;
  int r = sd_handle_write(h, data->data, data->len, &e);
  if (r != SD_IO_OK) err = fs_io_error("write", f, r, e);
  sd_handle_release(h);
  return err;
}

void sd_lib_fs_File_close(sd_S_fs_File f) {
  int64_t id;
  if (sd_int_to_i64(f.f_id, &id)) (void)sd_handle_close(id);
}

/* The natives above that use the file system directly run in block
 * sections (seed.h): a slow disk or a FIFO must not hold up the other
 * goroutines. */

sd_err sd_lib_fs_write(sd_str path, sd_str data) {
  sd_block_begin();
  sd_err r = fs_write_blocking(path, data);
  sd_block_end();
  return r;
}

sd_err sd_lib_fs_append(sd_str path, sd_str data) {
  sd_block_begin();
  sd_err r = fs_append_blocking(path, data);
  sd_block_end();
  return r;
}

sd_err sd_lib_fs_stat(sd_str path, sd_S_fs_Info *out) {
  sd_block_begin();
  sd_err r = fs_stat_blocking(path, out);
  sd_block_end();
  return r;
}

sd_err sd_lib_fs_mkdir(sd_str path) {
  sd_block_begin();
  sd_err r = fs_mkdir_blocking(path);
  sd_block_end();
  return r;
}

sd_err sd_lib_fs_rename(sd_str from, sd_str to) {
  sd_block_begin();
  sd_err r = fs_rename_blocking(from, to);
  sd_block_end();
  return r;
}

sd_err sd_lib_fs_remove(sd_str path) {
  sd_block_begin();
  sd_err r = fs_remove_blocking(path);
  sd_block_end();
  return r;
}

sd_err sd_lib_fs_removeAll(sd_str path) {
  sd_block_begin();
  sd_err r = fs_removeAll_blocking(path);
  sd_block_end();
  return r;
}

sd_err sd_lib_fs_makeTemp(sd_str prefix, sd_str *out) {
  sd_block_begin();
  sd_err r = fs_makeTemp_blocking(prefix, out);
  sd_block_end();
  return r;
}

/* ---- lib/fmt/fmt.c ---- */
/* Natives of package fmt (runtime/README.md, "Native functions"). */

#include <math.h>
#include <stdio.h>
#include <stdlib.h>

void sd_lib_fmt_print(sd_str s) { sd_fmt_print(s); }

void sd_lib_fmt_println(sd_str s) { sd_fmt_println(s); }

void sd_lib_fmt_eprint(sd_str s) { sd_fmt_eprint(s); }

void sd_lib_fmt_eprintln(sd_str s) { sd_fmt_eprintln(s); }

/* The C library's printf is correctly rounded (round-half-even on the exact
 * binary value) on macOS and glibc. nan is spelled out so that no "-nan"
 * appears. */
sd_str sd_lib_fmt_fixed(double f, sd_int places) {
  int64_t p;
  if (!sd_int_to_i64(places, &p) || p < 0 || p > 100) {
    sd_crash_int("fmt.fixed: places (%s) must be between 0 and 100", places);
  }
  if (isnan(f)) return sd_str_from_cstr("nan");
  if (isinf(f)) return sd_str_from_cstr(f > 0 ? "inf" : "-inf");
  int n = snprintf(NULL, 0, "%.*f", (int)p, f);
  char *buf = sd_alloc((size_t)n + 1);
  snprintf(buf, (size_t)n + 1, "%.*f", (int)p, f);
  sd_str out = sd_str_new(buf, n);
  free(buf);
  return out;
}

/* ---- lib/os/os.c ---- */
/* Natives of package os (runtime/README.md, "Native functions"). */

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <spawn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

extern char **environ;

void sd_lib_os_exit(sd_int code) { sd_os_exit(code); }

void sd_lib_os_crash(sd_str message) { sd_os_crash(message); }

sd_str sd_lib_os_env(sd_str name) { return sd_os_env(name); }

/* Arguments go to the OS as C strings, which end at the first NUL byte, so
 * an argument with a NUL inside would silently become a different one
 * ("rm\0 -rf" would run rm). That is an error, before anything starts; the
 * program is shown with each NUL as \x00. */
static sd_err os_check_argv(const char *fn, const sd_list *argv) {
  sd_str const *xs = sd_list_data(argv);
  for (int64_t i = 0; i < argv->len; i++) {
    if (xs[i]->len == 0 || !memchr(xs[i]->data, 0, (size_t)xs[i]->len)) continue;
    sd_str p = xs[0];
    char *shown = sd_alloc((size_t)p->len * 4 + 1), *q = shown;
    for (int64_t j = 0; j < p->len; j++) {
      if (p->data[j] == 0) {
        memcpy(q, "\\x00", 4);
        q += 4;
      } else {
        *q++ = p->data[j];
      }
    }
    *q = 0;
    sd_err e = i == 0 ? sd_errorf("%s: %s: program name contains a NUL byte", fn, shown)
                      : sd_errorf("%s: %s: argument %lld contains a NUL byte", fn, shown, (long long)i);
    free(shown);
    return e;
  }
  return SD_ERR_NULL;
}

sd_err sd_lib_os_run(sd_list *argv, sd_int *code) {
  if (argv->len > 0) {
    sd_err e = os_check_argv("os.run", argv);
    if (!sd_err_is_null(e)) return e;
  }
  return sd_os_run(argv, code);
}

sd_str sd_lib_os_executable(void) { return sd_os_executable(); }

sd_err sd_lib_os_cwd(sd_str *out) { return sd_os_cwd(out); }

/* os.output: os.run with the child's stdout on a pipe. Both pipe ends are
 * close-on-exec, so no other child started at the same time inherits them;
 * dup2 onto the child's descriptor 1 clears the flag there. Reading waits
 * with sd_wait_fd and the end with sd_wait_child, so both are stop points:
 * a stopped goroutine kills and reaps the child. */
sd_err sd_lib_os_output(sd_list *argv, sd_str *out, sd_int *code) {
  if (argv->len == 0) sd_crash("os.output: argv is empty");
  sd_err bad = os_check_argv("os.output", argv);
  if (!sd_err_is_null(bad)) return bad;
  sd_str const *xs = sd_list_data(argv);
  char **av = sd_alloc((size_t)(argv->len + 1) * sizeof(char *));
  for (int64_t i = 0; i < argv->len; i++) av[i] = (char *)xs[i]->data;
  av[argv->len] = NULL;
  int fds[2];
  if (pipe(fds) != 0) {
    sd_err e = sd_errorf("os.output: %s: %s", av[0], sd_strerror(errno));
    free(av);
    return e;
  }
  fcntl(fds[0], F_SETFD, FD_CLOEXEC);
  fcntl(fds[1], F_SETFD, FD_CLOEXEC);
  posix_spawn_file_actions_t fa;
  posix_spawn_file_actions_init(&fa);
  posix_spawn_file_actions_adddup2(&fa, fds[1], 1);
  sd_block_begin(); /* the flushes may block, and so may posix_spawnp */
  fflush(stdout);
  fflush(stderr);
  pid_t pid;
  int r = posix_spawnp(&pid, av[0], &fa, NULL, av, environ);
  sd_block_end();
  posix_spawn_file_actions_destroy(&fa);
  close(fds[1]);
  if (r != 0) {
    close(fds[0]);
    sd_err e = sd_errorf("os.output: %s: %s", av[0], sd_strerror(r));
    free(av);
    return e;
  }
  int64_t cap = 4096, n = 0;
  char *buf = sd_alloc((size_t)cap);
  int readErr = 0;
  int st = 0;
  for (;;) {
    int w = sd_wait_fd(fds[0], false, 0);
    if (w == SD_WAIT_STOP) {
      close(fds[0]);
      free(buf);
      free(av);
      (void)sd_wait_child(pid, &st); /* the goroutine is stopped: kills and reaps the child */
      sd_stop();
    }
    if (w == SD_WAIT_FAILED) {
      if (errno == EINTR || errno == EAGAIN) continue;
      readErr = errno;
      break;
    }
    if (n == cap) {
      cap *= 2;
      buf = sd_realloc(buf, (size_t)cap);
    }
    ssize_t got = read(fds[0], buf + n, (size_t)(cap - n));
    if (got < 0 && (errno == EINTR || errno == EAGAIN)) continue;
    if (got < 0) readErr = errno;
    if (got <= 0) break;
    n += got;
  }
  close(fds[0]);
  int waitErr = sd_wait_child(pid, &st);
  if (waitErr == SD_WAIT_STOP) {
    free(buf);
    free(av);
    sd_stop();
  }
  if (readErr || waitErr) {
    sd_err e = sd_errorf("os.output: %s: %s", av[0], sd_strerror(readErr ? readErr : waitErr));
    free(buf);
    free(av);
    return e;
  }
  free(av);
  *out = sd_str_new(buf, n);
  free(buf);
  *code = SD_INT(WIFEXITED(st) ? WEXITSTATUS(st) : 128 + (WIFSIGNALED(st) ? WTERMSIG(st) : 0));
  return SD_ERR_NULL;
}

sd_err sd_lib_os_hostname(sd_str *out) {
  char buf[1024];
  if (gethostname(buf, sizeof buf - 1) != 0) return sd_errorf("os.hostname: %s", sd_strerror(errno));
  buf[sizeof buf - 1] = 0;
  *out = sd_str_from_cstr(buf);
  return SD_ERR_NULL;
}

/* ---- lib/io/io.c ---- */
/* Natives of package io (runtime/README.md, "Native functions"). Stdin is a
 * handle of the runtime's table (kind SD_HANDLE_STDIN), so that its reads
 * are stop points, serialised between goroutines and buffered. */

#include <pthread.h>
#include <stdio.h>

static int64_t io_stdin_id;
static pthread_once_t io_stdin_once = PTHREAD_ONCE_INIT;

static void io_stdin_init(void) { io_stdin_id = sd_handle_new(SD_HANDLE_STDIN, 0, ""); }

static sd_handle *io_stdin(void) {
  pthread_once(&io_stdin_once, io_stdin_init);
  sd_block_begin(); /* stdout may be a full pipe */
  fflush(stdout);
  sd_block_end();
  return sd_handle_acquire(io_stdin_id, SD_HANDLE_STDIN);
}

sd_err sd_lib_io_readLine(sd_str *out) {
  sd_handle *h = io_stdin();
  int err = 0;
  int r = sd_handle_read_line(h, out, &err);
  sd_err e = SD_ERR_NULL;
  if (r != SD_IO_OK && r != SD_IO_EOF) e = sd_handle_error("io.readLine", h, SD_HANDLE_STDIN, r, err);
  sd_handle_release(h);
  return e;
}

sd_err sd_lib_io_read(sd_int max, sd_str *out) {
  int64_t m;
  if (!sd_int_to_i64(max, &m)) m = sd_int_lt(max, SD_INT(0)) ? -1 : INT64_MAX;
  if (m < 1) {
    sd_crash_int("io.read: max (%s) must be at least 1", max);
  }
  sd_handle *h = io_stdin();
  int err = 0;
  int r = sd_handle_read(h, m, out, &err);
  sd_err e = SD_ERR_NULL;
  if (r != SD_IO_OK && r != SD_IO_EOF) e = sd_handle_error("io.read", h, SD_HANDLE_STDIN, r, err);
  sd_handle_release(h);
  return e;
}

sd_err sd_lib_io_readAll(sd_str *out) {
  sd_handle *h = io_stdin();
  int err = 0;
  int r = sd_handle_read_all(h, out, &err);
  sd_err e = SD_ERR_NULL;
  if (r != SD_IO_OK) e = sd_handle_error("io.readAll", h, SD_HANDLE_STDIN, r, err);
  sd_handle_release(h);
  return e;
}

/* ---- lib/crypto/crypto.c ---- */
/* Natives of package crypto (runtime/README.md, "Native functions"):
 * SHA-256 (FIPS 180-4), HMAC-SHA-256 (RFC 2104), OS randomness and a
 * constant-time comparison. */

#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#if defined(__APPLE__)
#include <sys/random.h>
#endif

/* ---------------------------------------------------------------- SHA-256 */

typedef struct {
  uint32_t h[8];
  uint64_t total; /* bytes hashed so far */
  uint8_t block[64];
  size_t used; /* bytes in block */
} crypto_sha256_ctx;

static const uint32_t crypto_sha256_k[64] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
};

#define CRYPTO_ROTR(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

static void crypto_sha256_init(crypto_sha256_ctx *c) {
  static const uint32_t h0[8] = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
                                 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19};
  memcpy(c->h, h0, sizeof h0);
  c->total = 0;
  c->used = 0;
}

static void crypto_sha256_block(crypto_sha256_ctx *c, const uint8_t *p) {
  uint32_t w[64];
  for (int i = 0; i < 16; i++)
    w[i] = (uint32_t)p[4 * i] << 24 | (uint32_t)p[4 * i + 1] << 16 | (uint32_t)p[4 * i + 2] << 8 | (uint32_t)p[4 * i + 3];
  for (int i = 16; i < 64; i++) {
    uint32_t s0 = CRYPTO_ROTR(w[i - 15], 7) ^ CRYPTO_ROTR(w[i - 15], 18) ^ (w[i - 15] >> 3);
    uint32_t s1 = CRYPTO_ROTR(w[i - 2], 17) ^ CRYPTO_ROTR(w[i - 2], 19) ^ (w[i - 2] >> 10);
    w[i] = w[i - 16] + s0 + w[i - 7] + s1;
  }
  uint32_t a = c->h[0], b = c->h[1], cc = c->h[2], d = c->h[3], e = c->h[4], f = c->h[5], g = c->h[6], h = c->h[7];
  for (int i = 0; i < 64; i++) {
    uint32_t S1 = CRYPTO_ROTR(e, 6) ^ CRYPTO_ROTR(e, 11) ^ CRYPTO_ROTR(e, 25);
    uint32_t ch = (e & f) ^ (~e & g);
    uint32_t t1 = h + S1 + ch + crypto_sha256_k[i] + w[i];
    uint32_t S0 = CRYPTO_ROTR(a, 2) ^ CRYPTO_ROTR(a, 13) ^ CRYPTO_ROTR(a, 22);
    uint32_t maj = (a & b) ^ (a & cc) ^ (b & cc);
    uint32_t t2 = S0 + maj;
    h = g;
    g = f;
    f = e;
    e = d + t1;
    d = cc;
    cc = b;
    b = a;
    a = t1 + t2;
  }
  c->h[0] += a;
  c->h[1] += b;
  c->h[2] += cc;
  c->h[3] += d;
  c->h[4] += e;
  c->h[5] += f;
  c->h[6] += g;
  c->h[7] += h;
}

static void crypto_sha256_update(crypto_sha256_ctx *c, const uint8_t *p, size_t n) {
  c->total += n;
  if (c->used > 0) {
    size_t take = 64 - c->used < n ? 64 - c->used : n;
    memcpy(c->block + c->used, p, take);
    c->used += take;
    p += take;
    n -= take;
    if (c->used < 64) return;
    crypto_sha256_block(c, c->block);
    c->used = 0;
  }
  for (; n >= 64; p += 64, n -= 64) crypto_sha256_block(c, p);
  memcpy(c->block, p, n);
  c->used = n;
}

static void crypto_sha256_final(crypto_sha256_ctx *c, uint8_t out[32]) {
  uint64_t bits = c->total * 8;
  uint8_t pad[72] = {0x80};
  size_t padlen = (c->used < 56 ? 56 : 120) - c->used;
  for (int i = 0; i < 8; i++) pad[padlen + (size_t)i] = (uint8_t)(bits >> (56 - 8 * i));
  crypto_sha256_update(c, pad, padlen + 8);
  for (int i = 0; i < 8; i++) {
    out[4 * i] = (uint8_t)(c->h[i] >> 24);
    out[4 * i + 1] = (uint8_t)(c->h[i] >> 16);
    out[4 * i + 2] = (uint8_t)(c->h[i] >> 8);
    out[4 * i + 3] = (uint8_t)c->h[i];
  }
}

sd_str sd_lib_crypto_sha256(sd_str data) {
  crypto_sha256_ctx c;
  uint8_t out[32];
  crypto_sha256_init(&c);
  crypto_sha256_update(&c, (const uint8_t *)data->data, (size_t)data->len);
  crypto_sha256_final(&c, out);
  return sd_str_new((const char *)out, 32);
}

sd_str sd_lib_crypto_hmacSha256(sd_str key, sd_str data) {
  uint8_t k[64] = {0}, pad[64], inner[32], out[32];
  crypto_sha256_ctx c;
  if (key->len > 64) {
    crypto_sha256_init(&c);
    crypto_sha256_update(&c, (const uint8_t *)key->data, (size_t)key->len);
    crypto_sha256_final(&c, k);
  } else {
    memcpy(k, key->data, (size_t)key->len);
  }
  for (int i = 0; i < 64; i++) pad[i] = k[i] ^ 0x36;
  crypto_sha256_init(&c);
  crypto_sha256_update(&c, pad, 64);
  crypto_sha256_update(&c, (const uint8_t *)data->data, (size_t)data->len);
  crypto_sha256_final(&c, inner);
  for (int i = 0; i < 64; i++) pad[i] = k[i] ^ 0x5c;
  crypto_sha256_init(&c);
  crypto_sha256_update(&c, pad, 64);
  crypto_sha256_update(&c, inner, 32);
  crypto_sha256_final(&c, out);
  return sd_str_new((const char *)out, 32);
}

/* ------------------------------------------------------------- randomness */

/* Fills buf with n bytes from the OS: getentropy (at most 256 bytes per
 * call), or /dev/urandom where getentropy is missing or fails. Returns 0, or
 * the errno of the failure. (lib/rand/rand.c has its own copy for seeding:
 * a package's C helpers are static to it.) */
static int crypto_os_random(uint8_t *buf, size_t n) {
  size_t done = 0;
  while (done < n) {
    size_t chunk = n - done > 256 ? 256 : n - done;
    if (getentropy(buf + done, chunk) != 0) break;
    done += chunk;
  }
  if (done == n) return 0;
  int fd = open("/dev/urandom", O_RDONLY | O_CLOEXEC);
  if (fd < 0) return errno;
  while (done < n) {
    ssize_t r = read(fd, buf + done, n - done);
    if (r < 0 && errno == EINTR) continue;
    if (r <= 0) {
      int e = r < 0 ? errno : EIO;
      close(fd);
      return e;
    }
    done += (size_t)r;
  }
  close(fd);
  return 0;
}

sd_str sd_lib_crypto_randomBytes(sd_int n) {
  int64_t len;
  if (!sd_int_to_i64(n, &len) || len < 0) {
    if (sd_int_lt(n, SD_INT(0))) sd_crash_int("crypto.randomBytes: n (%s) must not be negative", n);
    sd_crash_int("crypto.randomBytes: n (%s) is too large", n);
  }
  if (len == 0) return sd_str_from_cstr("");
  uint8_t *buf = sd_alloc((size_t)len);
  int e = crypto_os_random(buf, (size_t)len);
  if (e != 0) {
    free(buf);
    sd_crash("crypto.randomBytes: the OS provided no randomness: %s", sd_strerror(e));
  }
  sd_str out = sd_str_new((const char *)buf, len);
  free(buf);
  return out;
}

/* The loop always runs over every byte, and the accumulator is volatile, so
 * the compiler cannot stop at the first difference. */
bool sd_lib_crypto_equal(sd_str a, sd_str b) {
  if (a->len != b->len) return false;
  volatile uint8_t diff = 0;
  const volatile uint8_t *x = (const volatile uint8_t *)a->data, *y = (const volatile uint8_t *)b->data;
  for (int64_t i = 0; i < a->len; i++) diff |= x[i] ^ y[i];
  return diff == 0;
}
#ifndef SD_DIVC_
#define SD_DIVC_
/* x / c for 0 <= x < 2^62 and a constant c > 0, as (x * m) >> (64 + s) (gen_int.sd). */
static inline __attribute__((unused)) int64_t sd_divc_(int64_t x, uint64_t m, int s, int64_t c) {
#ifdef __SIZEOF_INT128__
  (void)c;
  return (int64_t)((uint64_t)(((unsigned __int128)(uint64_t)x * m) >> 64) >> s);
#else
  (void)m; (void)s;
  return (int64_t)((uint64_t)x / (uint64_t)c);
#endif
}
static inline __attribute__((unused)) int64_t sd_modc_(int64_t x, uint64_t m, int s, int64_t c) {
  return x - sd_divc_(x, m, s, c) * c;
}
#endif
